{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Replace each block’s GELU feed-forward sublayer with GEGLU using two 2H-wide branches. Preserve bidirectional attention, normalization, residual paths, embeddings, masked training, readout, loss and optimizer. The predictor imports the updated model class, keeping checkpoint shapes consistent across all four category models.",
      "edits": [
        {
          "find": "class BERT4RecModel(nn.Module):",
          "replace": "class GEGLUTransformerEncoderLayer(nn.TransformerEncoderLayer):\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.linear1 = nn.Linear(\n            self.linear1.in_features,\n            self.linear1.out_features * 2,\n            bias=self.linear1.bias is not None,\n        )\n        # Disable the fused GELU/ReLU path so evaluation uses the gated sublayer.\n        self.activation_relu_or_gelu = 0\n\n    def _ff_block(self, x: torch.Tensor) -> torch.Tensor:\n        value, gate = self.linear1(x).chunk(2, dim=-1)\n        gated = value * torch.nn.functional.gelu(gate)\n        return self.dropout2(self.linear2(self.dropout(gated)))\n\n\nclass BERT4RecModel(nn.Module):"
        },
        {
          "find": "        encoder_layer = nn.TransformerEncoderLayer(",
          "replace": "        encoder_layer = GEGLUTransformerEncoderLayer("
        }
      ]
    }
  ],
  "change_summary": "Use GEGLU feed-forward sublayers in every category’s BERT4Rec model, with matching inference through the existing predictor import."
}
